final_sql:
with b as (
  select year(p.date_taken) as yr, l.gate_category, j.photo_id is null as excluded
  from photos p join labels l using(photo_id) left join jwst_space_images j using(photo_id)
  where p.date_taken >= '2022-01-01' and p.date_taken < '2026-01-01'
), tot as (
  select yr, count(*) as labelled, round(100.0*avg(excluded::int),1) as pct_not_published from b group by yr
), top as (
  select yr, gate_category, row_number() over (partition by yr order by count(*) desc, gate_category) rn
  from b where excluded group by yr, gate_category
)
select t.yr as year, t.labelled as labelled_count, t.pct_not_published, top.gate_category as top_excluded_gate_category
from tot t left join top on top.yr = t.yr and top.rn = 1 order by t.yr
